/** Independent fixed-source oracle; no producer/answer imports and no code eval. */
import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import type{AnswerPart}from'../../src/core/types';
import facts from'./legacy-2019-pm-ranking-facts.json';
export type RankingRecord={student:number;school:number;scores:number[]};
const sum=(r:RankingRecord)=>r.scores.reduce((a,b)=>a+b,0);
export function rankingReference(rs:RankingRecord[],policy:number){assert(rs.length>=5&&rs.length<=999);assert.equal(new Set(rs.map(r=>r.student)).size,rs.length);assert.deepEqual([...new Set(rs.map(r=>r.school))].sort(),[1,2,3,4,5]);rs.forEach(r=>{assert(r.scores.length===5&&r.scores.every(x=>Number.isInteger(x)&&x>=0&&x<=100));});const rows=rs.map(r=>{const better=(s:RankingRecord)=>policy?sum(s)<sum(r):sum(s)>sum(r);return[1+rs.filter(better).length,r.student,r.school,1+rs.filter(s=>s.school===r.school&&better(s)).length,sum(r)];}),counts=[1,2,3,4,5].map(k=>rs.filter(r=>r.school===k).length),totals=[1,2,3,4,5].map(k=>rs.filter(r=>r.school===k).reduce((n,r)=>n+sum(r),0));return{rows,counts,totals,overallTenth:Math.floor(rs.reduce((n,r)=>n+sum(r),0)*10/rs.length),schoolTenths:totals.map((n,i)=>Math.floor(n*10/counts[i]))};}
const record=(total:number,school:number,student:number):RankingRecord=>{const scores=Array(5).fill(0);let t=total;for(let i=0;i<5;i++){scores[i]=Math.min(t,100);t-=scores[i];}assert.equal(t,0);return{student,school,scores};};
export function rankingWitnesses(full=false){const levels=full?[0,250,500]:[0,250],out:RankingRecord[][]=[];for(const a of levels)for(const b of levels)for(const c of levels)for(const d of levels)for(const e of levels){const rows=[a,b,c,d,e].map((t,i)=>record(t,i+1,[182025,181007,182038,185011,183007][i]));out.push(rows);for(let k=1;k<=5;k++)for(const t of levels)out.push([...rows,record(t,k,184010)]);}if(full)assert.equal(out.length,3888);return out;}
export function rankingState(rs:RankingRecord[],policy:number,candidate?:{part:string;text:string},reverseTies=false){let sort=(policy?'ASCENDING':'DESCENDING')+' KEY SRT-TOTAL',inc='ADD 1 TO ALL-ORD-NO BLD-ORD-NO(SRT-BLD)',globalMove='MOVE ALL-ORD-NO TO ALL-RANK',localMove='MOVE BLD-ORD-NO(SRT-BLD) TO BLD-RANK(SRT-BLD)';if(candidate){if(candidate.part==='a')sort=candidate.text;if(candidate.part==='b')inc=candidate.text;if(candidate.part==='c')globalMove=candidate.text;if(candidate.part==='d')localMove=candidate.text;}const sm=sort.match(/^(ASCENDING|DESCENDING) KEY SRT-(NO|TOTAL)$/);assert(sm,'Unknown fixed SORT option');let stream=[...rs].sort((x,y)=>((sm[2]==='NO'?x.student:sum(x))-(sm[2]==='NO'?y.student:sum(y)))*(sm[1]==='DESCENDING'?-1:1));if(reverseTies&&sm[2]==='TOTAL')stream=stream.flatMap((r,i)=>i&&sum(r)===sum(stream[i-1])?[]:stream.filter(s=>sum(s)===sum(r)).reverse());let ord=0,rank=0,previous=policy?-1:999;let localOrd=Array(5).fill(0),localRank=Array(5).fill(0),localPrevious=Array(5).fill(previous);const out:number[][]=[];
 const move=(t:string,k:number)=>{const m=t.match(/^MOVE (.+) TO (ALL-RANK|BLD-RANK\(SRT-BLD\))$/);assert(m,'Unknown fixed MOVE option');const from=m[1]==='ALL-CR-TOTAL'?previous:m[1]==='ALL-ORD-NO'?ord:m[1]==='BLD-ORD-NO(SRT-BLD)'?localOrd[k]:m[1]==='BLD-CR-TOTAL(SRT-BLD)'?localPrevious[k]:NaN;assert(Number.isFinite(from));if(m[2]==='ALL-RANK')rank=from;else localRank[k]=from;};
 for(const r of stream){const k=r.school-1,t=sum(r);if(inc==='ADD 1 TO ALL-ORD-NO BLD-ORD-NO(SRT-BLD)'){ord++;localOrd[k]++;}else if(inc==='ADD 1 TO ALL-RANK BLD-RANK(SRT-BLD)'){rank++;localRank[k]++;}else if(inc==='INITIALIZE BLD-INF'){localOrd=Array(5).fill(0);localRank=Array(5).fill(0);localPrevious=Array(5).fill(0);}else{assert.equal(inc,'MOVE ALL-ORD-NO TO BLD-ORD-NO(SRT-BLD)');localOrd[k]=ord;}if(policy?t>previous:t<previous){previous=t;move(globalMove,k);}if(policy?t>localPrevious[k]:t<localPrevious[k]){localPrevious[k]=t;move(localMove,k);}out.push([rank,r.student,r.school,localRank[k],t]);}return{rows:out,counts:localOrd,ranks:localRank};}
function rowEqual(actual:number[][],ref:number[][],policy:number){return JSON.stringify([...actual].sort((a,b)=>a[1]-b[1]))===JSON.stringify([...ref].sort((a,b)=>a[1]-b[1]))&&actual.every((r,i)=>!i||(policy?r[4]>=actual[i-1][4]:r[4]<=actual[i-1][4]));}
export function rankingChoiceTruth(part:string,text:string,policy:number,rs:RankingRecord[]){const ref=rankingReference(rs,policy);if('abcd'.includes(part))return rowEqual(rankingState(rs,policy,{part,text}).rows,ref.rows,policy);if(part==='e'){assert(facts.groups.e.includes(text));if(text==='行番号79の後ろ')return true;return false;/* Other sites execute once outside per-row loops or before current record initialization. No expired buffer is assumed defined. */}assert.equal(part,'f');const m=text.match(/^BLD-TOTAL\(CNT\) \/ BLD-(ORD-NO|RANK)\((CNT|SRT-BLD)\)$/);assert(m,'Unknown fixed mean option');const st=rankingState(rs,policy);return[0,1,2,3,4].every(buffer=>ref.totals.every((n,k)=>{const i=m[2]==='CNT'?k:buffer,den=m[1]==='ORD-NO'?st.counts[i]:st.ranks[i];return den>0&&Math.floor(n*10/den)===ref.schoolTenths[k];}));}
export function verifyRankingChoices(b:GeneratedBody,policy:number,full=false){const datasets=rankingWitnesses(full),truths:boolean[][]=[];let tested=0;for(let i=0;i<6;i++){const part='abcdef'[i];const p:AnswerPart=b.answerParts![i];const values=p.choiceIds.map(id=>{const c=b.choices[Number(id.split('-').at(-1))-1];assert(c.length===1&&c[0].type==='paragraph');return(c[0]as{type:'paragraph';text:string}).text;}),truth=values.map(text=>{for(const rs of datasets){tested++;if(!rankingChoiceTruth(part,text,policy,rs))return false;}return true;});assert.equal(truth.filter(Boolean).length,1,part);const a=b.partAnswers!.find(a=>a.kind==='choice'&&a.partId===p.id)!;assert(a.kind==='choice');assert.equal(a.choiceId,p.choiceIds[truth.indexOf(true)]);truths.push(truth);}return{datasets:datasets.length,choiceReferences:truths.reduce((n,t)=>n+t.length,0),truths,tested};}
const expectedText=(text:string,v:number)=>v?text.replaceAll('得点','失点').replaceAll('合計点','合計失点').replaceAll('平均点','平均失点').replaceAll('降順','昇順').replace('合計失点の高い塾生から','合計失点の少ない塾生から').replaceAll('492点','8点').replaceAll('488点','12点').replaceAll('487点','13点'):text;
export function assertLegacy2019RankingBody(b:GeneratedBody,values:readonly number[]){assert(values.length===1&&(values[0]===0||values[0]===1));const v=values[0],units=facts.units.filter(u=>u.kind!=='choices');assert.equal(b.prompt.length,22);assert.equal(b.choices.length,22);assert.equal(b.answerParts?.length,6);assert.equal(b.partAnswers?.length,6);const groupNames=['a','b','cd','cd','e','f']as const,offsets=[0,4,8,8,14,18];for(let i=0;i<6;i++){const p:AnswerPart=b.answerParts![i],group=facts.groups[groupNames[i]];assert.equal(p.id,'part-'+'abcdef'[i]);assert.equal(p.label,'設問'+(i<4?1:2)+' '+'abcdef'[i]);assert.deepEqual(p.choiceIds,group.map((_,j)=>'choice-value-'+(offsets[i]+j+1)));group.forEach((t,j)=>assert.deepEqual(b.choices[offsets[i]+j],[{type:'paragraph',text:t}]));}assert.deepEqual(b.answerParts![2].choiceIds,b.answerParts![3].choiceIds);assert(b.partAnswers!.every(a=>a.kind==='choice'));let fi=0;units.forEach((u,i)=>{const actual=b.prompt[i+2];if(u.kind==='code'){assert(actual.type==='code');assert.equal(actual.language,'cobol');const lines=actual.text.split('\n');assert.equal(lines.length,79);facts.program.forEach((line,j)=>{let t=line.text;if(v&&(line.number===31||line.number===35))t=t.replace('PIC 9(3)','PIC S9(3)').replace('VALUE 999','VALUE -1');if(v&&(line.number===65||line.number===69))t=t.replace(' < ',' > ');assert.equal(lines[j],String(line.number).padStart(2,'0')+'  '+t.replace(/\[([abcd])\]/g,'［$1］'));});}else if(u.kind==='figure'||u.kind==='table'){assert(actual.type==='diagram'&&actual.scene.kind==='source_figure');assert.equal(actual.scene.profile,facts.profiles[fi]);assert.deepEqual(actual.scene.values,[[0],[v],[v],[0],[0]][fi]);assert.equal(actual.caption,u.text);assert(actual.alt.length>30&&actual.alt.length<2000);fi++;}else{assert(actual.type==='paragraph');assert.equal(actual.text,expectedText(u.text,v));}});assert.equal(fi,5);for(const t of['ALL-ORD-NO','BLD-ORD-NO','ALL-RANK','BLD-RANK','SRT-BLD','小数第2位以降','1人以上','同点'])assert(b.explanation.includes(t));assert(b.explanation.includes(v?'平均失点':'平均点'));verifyRankingChoices(b,v);}
